/*
I started out this challenge blind. After doing some research I attracted to the design of some of the early Mesoamerican screenfolds
and codices. I knew I wouldn't be able to create the colourful characters through my generative art, so I took a different approach.
Since the codices seem to tell some of linear story in a grid format, often with a larger, more detailed, panel, I decided to start with a large
generated pattern made of circles and triangles and have simpler versions with less colours and shapes in the smaller panels. The "reading order" could 
use some work, but there does seem to be progression through the piece.

I also darkened some areas to mimic some of the tanning that would have been used on the skins and bark and some rubbed out sections which seemed to
have occurred over time in the actual codices.

WCCChallenge Topic - Chalchiuhtlicue (or Mesoamerican design)

Join the Birb's Nest Discord for friendly creative coding community
and future challenges and contributions: https://discord.gg/S8c7qcjw2b
WCCC-Contributions: https://openprocessing.org/curation/78544
*/

let stain, wear, picture
let palette
let gridColor, bg
let backgrounds
let cells = []

class Cell {
    constructor(x,y,w,h, mod, size = 'small') {
        this.x = x
        this.y = y
        this.w = w
        this.h = h
        this.mod = mod
        this.size = size
    }
    show(canvas, total) {
        canvas.strokeWeight(3)
        canvas.stroke(gridColor)
        canvas.noFill()
        canvas.beginShape()
			//noise to make the borders appear more handdrawn
        for (let i = this.x; i<this.x+this.w; i+=5) {
            canvas.vertex(i,this.y+ map(noise(i/100,this.y/100),0,1,-5,5))
        }
        for (let j = this.y; j<this.y+this.h; j+=5) {
            canvas.vertex(this.x+this.w+map(noise((this.x+this.w)/100,j/100),0,1,-5,5),j)
        }
        for (let i = this.x+this.w; i>this.x; i-=5) {
            canvas.vertex(i,this.y+this.h+ map(noise(i/100,(this.y+this.h)/100),0,1,-5,5))
        }
        for (let j = this.y+this.h; j>this.y; j-=5) {
            canvas.vertex(this.x+map(noise(this.x/100,j/100),0,1,-5,5),j)

        }
        canvas.endShape(CLOSE)
        canvas.noStroke()

        const subW = this.w / 12
        const subH = this.h / 12
        //limit palette for earlier panels
				this.palette = palette.slice(0,Math.floor(map(this.mod/total, 0,1,palette.length,1)))


        const vary = 1
        for (let i = 2; i<10; i++) {
            for (let j = 2; j<10; j++) {
                canvas.fill(random(this.palette))
                const x = this.x + i * subW
                const y = this.y + j * subH
                for (let k = 0;k<2;k++) {
								//skip more often in earlier panels
                if (random(total) < this.mod){
                    continue
                }
                const dir = Math.floor(random(0,4))

								//triangle tiling, repeated twice
                if (dir == 0) {

                    canvas.triangle(x+random(-vary,vary),y+random(-vary,vary),
                    x+subW+random(-vary,vary),y+random(-vary,vary),
                    x+subW/2+random(-vary,vary), y+subH/2+random(-vary,vary))
                }
                else if (dir == 1) {
                    canvas.triangle(x+random(-vary,vary),y+subH+random(-vary,vary)
                    ,x+subW+random(-vary,vary),y+subH+random(-vary,vary),
                    x+subW/2+random(-vary,vary), y+subH/2+random(-vary,vary))
                }
                else if (dir == 2) {
                    canvas.triangle(x,y,
                        x,y+subH,
                        x+subW/2, y+subH/2)
                }
                else {
                    canvas.triangle(x+subW+random(-vary,vary),y+random(-vary,vary),
                        x+subW+random(-vary,vary),y+subH+random(-vary,vary),
                        x+subW/2+random(-vary,vary), y+subH/2+random(-vary,vary))
                }

            }
        }
        }
				//circles drawn around the tiling
        let r = this.w/5
        for (let i = this.x+r/2; i<this.x+this.w; i+=(Math.max(0.001, Math.abs(r)) || 1)) {
            if (random() > 0.25 && random(total) > this.mod) {
                canvas.fill(random(this.palette))
                canvas.circle(i,this.y+0.1*this.h,r*random(0.3,0.5))
            }
            if (random() > 0.25 && random(total) > this.mod) {
                canvas.fill(random(this.palette))
                canvas.circle(i,this.y+0.9*this.h,r*random(0.3,0.5))
            }
        }
        r = this.h / 5
        for (let j = this.y+1.5*r; j<this.y+this.h-r; j+=(Math.max(0.001, Math.abs(r)) || 1)) {
            if (random() > 0.25 && random(total) > this.mod) {
                canvas.fill(random(this.palette))
                canvas.circle(this.x+0.1*this.w,j,r*random(0.3,0.5))
            }
            if (random() > 0.25 && random(total) > this.mod) {
                canvas.fill(random(this.palette))
                canvas.circle(this.x+0.9*this.w,j,r*random(0.3,0.5))
            }    
        }
    }

}

function setup() {
	//split into 6 sections, 5 cells with 0.5 cell padding
    const dim = 6 * Math.floor(0.95*max(windowWidth, windowHeight))/6
    pixelDensity(1)
    createCanvas(dim,dim)
		//colours from various codices
    backgrounds = [
        [255,241,214],
        [230, 232, 229],
        [251,233,183]
    ]

    bg = random(backgrounds)

    palette = [
        [135,94,67],
        [109,85,57],
        [162,143,85],
        [73,74,79],
        [40,41,44],
        [172,93,92],
        [118,73,34],
        [97,21,25],
        [75,88,76],
        [200,153,61],
        [117,114,68],
        [93,57,30],
        [55,49,30]
    ]
    shuffle(palette,true)
    gridColor = palette.pop()
}

function draw() {
    // noLoop() removed for animationbackground(bg)
    stain = createGraphics(width/4,height/4)
    wear = createGraphics(width/4,height/4)
    picture = createGraphics(width,height)

    stain.noStroke()
    stain.pixelDensity(1)
    wear.noStroke()   
    wear.pixelDensity(1)
    picture.pixelDensity(1)
		//adding dark and light pieces, sized down to speed up the process
    for (let i = 0; i<width/4; i++) {
        for (let j = 0; j<height/4;j++) {
            const staining = map(noise(i/50,j/50),0,1,0,255)
            if (staining < 200) {
                stain.fill(staining,40)
                stain.circle(i,j,2)
            }
            const wearing = map(noise(i/100,j/100),0,1,0,dist(i,j,width/2,height/2))
            if (wearing > 0.25*width) {
                wear.fill(...bg,20)
                wear.circle(i,j,2)
            }
        }
    }

    image(stain, 0,0,width,height)


		//determine size and position of large panel
    const cellW = width / 6
    const cellH = height / 6
    const rectX = Math.floor(random(0,3))
    const rectY = Math.floor(random(0,3))
    const rectW = Math.floor(random(3,6-rectX))
    const rectH = Math.floor(random(3,6-rectY))
    const rectDim = min(rectW,rectH)

    const bigRect = new Cell((rectX+0.5)*cellW,(rectY+0.5)*cellH,rectDim*cellW,rectDim*cellH, 0,'large')
    for (let i = 0; i<5;i++) {
        for (let j = 0; j<5;j++) {
            if (i >= rectX && i <rectX+rectDim &&
                j >= rectY && j < rectY+rectDim) {
                continue
            }
            cells.push(new Cell((i +0.5) * cellW, (j+0.5)*cellH,cellW,cellH,cells.length+1))
        }
    }

    bigRect.show(picture,cells.length+1)
		//create small panels around big panel
    for (const cell of cells) {
        cell.show(picture,cells.length+1)
    }
		//Fully erase some areas, more around the edges than the center.
    picture.erase()
    picture.noStroke()
    for (let i = 0; i<width; i++) {
        for (let j = 0; j<height;j++) {
            const extremeWear = map(noise(i/25+10000,j/25+10000),0,1,0,dist(i,j,width/2,height/2))
            if (extremeWear >0.3*width) {
                picture.fill(...bg,255)
                picture.circle(i,j,2)
            }

        }
    }
    picture.noErase()
    image(picture,0,0)
    image(wear,0,0,width,height)
}
